def number_to_words(n: int) -> str:
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer between 0 and 999999")
    if n < 0 or n > 999999:
        raise ValueError("n must be between 0 and 999999")

    ones = [
        "zero", "one", "two", "three", "four", "five", "six", "seven",
        "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen",
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety",
    ]

    def under_hundred(x: int) -> str:
        if x < 20:
            return ones[x]
        t, u = divmod(x, 10)
        return tens[t] if u == 0 else tens[t] + "-" + ones[u]

    def under_thousand(x: int) -> str:
        parts = []
        h, rest = divmod(x, 100)
        if h:
            parts.append(ones[h] + " hundred")
        if rest or not h:
            parts.append(under_hundred(rest))
        return " ".join(parts)

    if n == 0:
        return "zero"

    thousands, remainder = divmod(n, 1000)
    words = []
    if thousands:
        words.append(under_thousand(thousands) + " thousand")
    if remainder:
        words.append(under_thousand(remainder))
    return " ".join(words)
```

The helper `under_thousand` only emits the trailing part when it is nonzero (or when there is no hundreds part at all), so `1000` gives `'one thousand'` and `105` gives `'one hundred five'`.
